customElements.define('search-funnel',class extends HTMLElement{constructor(){super();this.SEARCH_INPUT='[data-search-input]';this.CLEAR_INPUT='[data-clear-input]';this.FILTER_TOGGLE='[data-search-filter]';this.SUBMIT_SEARCH='[data-submit-search]';this.CLEAR_FILTERS_GROUP='[data-clear-group-filters]';this.TAB_TAG_BADGE='[data-tag-badge]';this.activeFilters={type:[],regions:[],themes:[],search_species:[],subtopics:[]};this.hasSearchInput=!1;this.hasFilters=!1}
connectedCallback(){this.setupComponent()}
setupComponent(){this.searchInputElement=this.querySelector(this.SEARCH_INPUT);this.clearInputBtnElement=this.querySelector(this.CLEAR_INPUT);this.submitSearchBtnElement=this.querySelector(this.SUBMIT_SEARCH);this.tabGroupBadgeElements=Array.from(this.querySelectorAll(this.TAB_TAG_BADGE));this.tabGroupBadgeElements.forEach(badge=>{badge.classList.add("hide")});this.searchFilterElements=Array.from(this.querySelectorAll(this.FILTER_TOGGLE));this.clearToggleGroupElements=Array.from(this.querySelectorAll(this.CLEAR_FILTERS_GROUP));this.clearToggleGroupElements.forEach(clearBtn=>{clearBtn.classList.add("hide")});this.hasSearchInput=!!this.searchInputElement;this.hasFilters=this.searchFilterElements.length>0;this.setupListeners()}
setupListeners(){if(this.hasSearchInput){this.searchInputElement.addEventListener('input',()=>{this.updateSubmitURL()});if(this.clearInputBtnElement){this.clearInputBtnElement.addEventListener('click',()=>{this.clearSearchInput()})}}
if(this.hasFilters){this.searchFilterElements.forEach(toggle=>{toggle.addEventListener('click',(e)=>{this.updateActiveFilters(e)})});this.clearToggleGroupElements.forEach(toggle=>{toggle.addEventListener('click',(e)=>{this.clearFilterCategory(e)})})}}
updateActiveFilters(e){const{name,value}=e.currentTarget;const currentCategory=this.activeFilters[name];const tagIndex=currentCategory.indexOf(value);if(tagIndex>-1){currentCategory.splice(tagIndex,1)}else{currentCategory.push(value)}
this.groupUIUpdate(currentCategory.length,name);this.updateSubmitURL()}
clearFilterCategory(e){const{name}=e.currentTarget;const currentCategory=this.activeFilters[name];const categoryBtns=this.searchFilterElements.filter(toggle=>{return toggle.name===name});categoryBtns.forEach(toggle=>{toggle.classList.remove("active")});currentCategory.length=0;this.groupUIUpdate(currentCategory.length,name);this.updateSubmitURL()}
updateSubmitURL(){if(!this.submitSearchBtnElement)
return;this.submitSearchBtnElement.href=this.buildURLEndpoint()}
clearSearchInput(){this.searchInputElement.value="";this.updateSubmitURL()}
groupUIUpdate(count,name){const clearGroupBtn=this.getClearToggleGroupBtn(name);const tagGroupBadge=this.getTabGroupBadge(name);if(count>0){if(clearGroupBtn){if(clearGroupBtn.classList.contains("hide")){clearGroupBtn.classList.remove("hide");clearGroupBtn.removeAttribute("disabled")}}
if(tagGroupBadge){if(tagGroupBadge.classList.contains("hide"))
tagGroupBadge.classList.remove("hide");tagGroupBadge.textContent=count}}else{if(clearGroupBtn){clearGroupBtn.classList.add("hide");clearGroupBtn.setAttribute("disabled","")}
if(tagGroupBadge){tagGroupBadge.classList.add("hide");tagGroupBadge.textContent="0"}}}
buildURLQuery(data){let searchParameters=new URLSearchParams(data);let emptyNullKeys=[];searchParameters.forEach((value,key)=>{if(value===''){emptyNullKeys.push(key)}});emptyNullKeys.forEach(key=>{searchParameters.delete(key)});return searchParameters.toString()}
buildURLEndpoint(){const domainOrigin=window.location.origin;const baseSubfolder="/ace-prototype/";const query=this.searchInputElement.value.toLowerCase().trim();const finalParameterObject={query,...this.activeFilters};const newQueries=`${this.buildURLQuery(finalParameterObject)}`;const relativePath=`${baseSubfolder}resources/?${newQueries}`;const endpoint=new URL(relativePath,domainOrigin);return endpoint}
getClearToggleGroupBtn(groupName){return this.clearToggleGroupElements.find(clearBtn=>clearBtn.name===groupName)??null}
getTabGroupBadge(groupName){return this.tabGroupBadgeElements.find(badge=>badge.dataset.groupName===groupName)??null}})